<template><AssetListShell title="Research" description="查看当前账号的研究结论及其数据完整度" :account-ref="store.account_ref" :items="items" :loading="loading" :error="error" :page-no="pageNo" :page-size="pageSize" :total="total" @page-change="load"><template #default="{ item }"><button class="asset-row" @click="router.push({ name: 'agentResearch', params: { artifactRef: item.ref } })"><span><strong>{{ item.topic || '未命名研究主题' }}</strong><small>{{ shortName(item.name) }} · 创建于 {{ formatTime(item.created_at) }} · 更新于 {{ formatTime(item.updated_at) }}</small></span><el-tag>{{ statusLabel(item.status) }}</el-tag></button></template></AssetListShell></template>
<script setup lang="ts">
import{onBeforeUnmount,onMounted,ref}from'vue';import{useRouter}from'vue-router';import AssetListShell from'@/components/AssetListShell.vue';import{getResearchList}from'@/api/unifiedAgent';import{useAgentChatStore}from'@/stores/agentChat';import{formatTime,statusLabel}from'@/utils/presentation';import type{ResearchSummary}from'@/types/productRead'
const store=useAgentChatStore(),router=useRouter(),items=ref<ResearchSummary[]>([]),loading=ref(false),error=ref(''),pageNo=ref(1),pageSize=20,total=ref(0);let controller:AbortController|null=null
const shortName=(value:string)=>value.length>60?`${value.slice(0,60)}…`:value
async function load(page=1){if(!store.account_ref)return;controller?.abort();controller=new AbortController();loading.value=true;error.value='';try{const result=await getResearchList(store.account_ref,page,pageSize,controller.signal);items.value=result.items;total.value=result.total;pageNo.value=result.page_no}catch(reason){if((reason as Error).name!=='CanceledError')error.value='研究列表加载失败，请稍后重试'}finally{loading.value=false}}
onMounted(()=>load());onBeforeUnmount(()=>controller?.abort())
</script>
